+.skeletonRail { display: grid; grid-template-columns: repeat(6, minmax(150px, 1fr)); gap: 12px; overflow: hidden; }
+.skeletonRail span { height: 120px; border-radius: 9px; background: linear-gradient(100deg, #0b1d29 20%, #163247 45%, #0b1d29 70%); background-size: 220% 100%; animation: shimmer 1.8s infinite linear; }
+@keyframes shimmer { to { background-position: -220% 0; } }
+
+.modalBackdrop { position: fixed; inset: 0; z-index: 200; display: grid; place-items: center; padding: 22px; background: #000c; backdrop-filter: blur(8px); }
+.modal { width: min(1000px, 100%); overflow: hidden; border: 1px solid #2a536d; border-radius: 14px; background: #04121d; box-shadow: 0 30px 100px #000d; }
+.modalHeader { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 12px 15px; }
